// GENERATED by docs/api/build-openapi-ts.mjs from docs/api/openapi.yaml — do not edit by hand.
export const OPENAPI_YAML = "openapi: 3.1.0\ninfo:\n  title: Covva API\n  version: 1.0.0\n  summary: REST API for the Covva mobile app and partner (broker/insurer) integrations.\n  description: |\n    Covva is a **technology platform**. It is not an insurer or broker, does not\n    give advice in its own name and never holds premiums. Every response that concerns a\n    transaction carries the information needed to show the mandatory disclosure.\n\n    ## Authentication\n    * **Customer / partner users** — `Authorization: Bearer <Supabase access token>` (mobile) or the\n      Supabase session cookie (web). Requests run as that user, so Postgres Row Level Security applies.\n    * **Partner integrations** — `x-api-key: imk_<prefix>_<secret>` (see `/partner/*`). Keys belong to a\n      broker or insurer organisation and carry scopes: `requests:read`, `quotes:write`,\n      `policies:issue`, `claims:write`, `policies:read`, `claims:read`, `finance:read` (or `*`).\n\n    ## Envelope\n    Every JSON response (except the AI chat stream and redirects) is an `ApiResult`:\n    `{ \"ok\": true, \"data\": … }` or `{ \"ok\": false, \"error\": { \"code\", \"message\", \"details?\" } }`.\n\n    | HTTP | `error.code` | Meaning |\n    |---|---|---|\n    | 400 | `invalid_input` | Validation failed (`details` lists `{ path, message }`) |\n    | 401 | `unauthorised` | Missing/expired token or invalid API key |\n    | 403 | `forbidden` | Authenticated but not allowed |\n    | 404 | `not_found` | Not found or not visible to you |\n    | 409 | `conflict` | Duplicate / already done |\n    | 422 | `business_rule` | A product rule blocked it (e.g. quote expired, broker not disclosed). Show `message` to the user. |\n    | 429 | `rate_limited` | Slow down; see `Retry-After` |\n    | 503 | `unavailable` | Feature switched off or not configured (AI, payments) |\n    | 500 | `internal_error` | Unexpected error; quote `x-request-id` to support |\n\n    Every response has an `x-request-id` header (send your own to correlate).\n\n    ## Client identification and platform access (Addendum 4)\n    Send `X-Covva-Client: mobile | web | partner-web` on every call (missing = `web`). Customers and\n    brokers use the mobile app; **insurer** (and staff) accounts are web-only: a call from `mobile` by an\n    account whose only memberships are insurer/staff gets `403 forbidden` with\n    `details.reason = \"insurer_web_only\"` and `details.portalUrl` — show the message and link to the web portal.\n    Dual-role users pick a workspace with `POST /me/workspace`; `GET /me` lists `workspaces` with `mobileAllowed`.\n\n    ## Product rules clients must honour\n    * Show the broker-of-record disclosure and record it (`POST /requests/{id}/disclosure`) **before** an application.\n    * Only `ready_to_accept` quotes can be applied for, and only before `valid_until`.\n    * Payment confirmation never activates cover. Show cover as active only when `policy.status = active`.\n    * Reporting a claim is not approval. Only the insurer decides claims.\n    * When `demoMode` is true, show \"Illustrative only · Demo data\" near insurer names and prices.\n    * AI output is labelled as AI-assisted and is never a suitability or claim decision.\n  contact:\n    name: Platform engineering\n    email: support@covva.com.gh\nservers:\n  - url: https://{host}/api/v1\n    variables:\n      host:\n        default: covva.com.gh\n  - url: http://localhost:3000/api/v1\nsecurity:\n  - bearerAuth: []\ntags:\n  - name: Webhooks\n    description: |\n      Signed HTTP callbacks to partner endpoints (configured in Team settings → Developer). Every delivery is a\n      `POST` with headers `x-covva-event`, `x-covva-delivery`, `x-covva-timestamp` and `x-covva-signature`\n      (`HMAC-SHA256(endpoint secret, \"{timestamp}.{raw body}\")`, hex). Respond 2xx within 10 s; failures retry after\n      1 min, 5 min, 30 min, 2 h and 12 h. Payloads carry ids, references, statuses, amounts and dates only — never\n      personal data; fetch details through the API. See `docs/WEBHOOKS.md`.\n  - name: Me\n  - name: Catalogue\n  - name: Lookups\n  - name: Requests\n  - name: Documents\n  - name: Applications & payments\n  - name: Policies\n  - name: Verification\n  - name: Claims\n  - name: Complaints\n  - name: Notifications & devices\n  - name: AI\n  - name: Family (diaspora)\n    description: |\n      Sponsors abroad look after family in Ghana: add **beneficiaries**, capture their **consent** by SMS/WhatsApp\n      code or signed link (never from the sponsor), link the payer to a policy with a **sponsorship** (optionally a\n      **gift** with a message the beneficiary reveals), see the **family dashboard** and report **claims by proxy**\n      with the beneficiary's `proxy_claims` consent. Both parties get documents, reminders and claim updates\n      (`notifications.recipient_role`).\n  - name: Partner API\n  - name: System\n\npaths:\n  /me:\n    get:\n      tags: [Me]\n      summary: Current user — profile, memberships, workspaces, feature flags, consent state\n      parameters: [{ $ref: \"#/components/parameters/CovvaClient\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Me\" }\n        \"401\": { $ref: \"#/components/responses/Error\" }\n        \"403\":\n          description: Insurer/staff account calling from the mobile app (`details.reason = insurer_web_only`)\n          content: { application/json: { schema: { $ref: \"#/components/schemas/ErrorEnvelope\" } } }\n    patch:\n      tags: [Me]\n      summary: Update own profile\n      description: KYC status can't be changed by the client (enforced in the database).\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/UpdateProfileInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"400\": { $ref: \"#/components/responses/Error\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /me/workspace:\n    post:\n      tags: [Me]\n      summary: Choose the active workspace (dual-role users)\n      description: |\n        Persists `profiles.active_workspace`. The workspace must be one of the caller's `workspaces` and usable from the\n        calling client — an insurer workspace cannot be activated with `X-Covva-Client: mobile`.\n      parameters: [{ $ref: \"#/components/parameters/CovvaClient\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/SetActiveWorkspaceInput\" } } }\n      responses:\n        \"200\":\n          description: Stored choice\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties:\n                      data:\n                        type: object\n                        properties:\n                          activeWorkspace: { $ref: \"#/components/schemas/ActiveWorkspace\" }\n                          workspace: { $ref: \"#/components/schemas/Workspace\" }\n        \"400\": { $ref: \"#/components/responses/Error\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n  /me/consents:\n    post:\n      tags: [Me]\n      summary: Record consent decisions (append-only)\n      description: When `version` is omitted the current `terms_version` / `privacy_version` is used.\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/RecordConsentsInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n\n  /catalog/categories:\n    get:\n      tags: [Catalogue]\n      summary: Insurance categories with availability and `risk_schema` (form definition)\n      security: []\n      responses:\n        \"200\":\n          description: Categories\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties: { data: { type: array, items: { $ref: \"#/components/schemas/Category\" } } }\n  /catalog/categories/{slug}:\n    get:\n      tags: [Catalogue]\n      summary: One category with approved products from participating insurers\n      security: []\n      parameters: [{ name: slug, in: path, required: true, schema: { type: string } }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"404\": { $ref: \"#/components/responses/Error\" }\n  /catalog/insurers:\n    get:\n      tags: [Catalogue]\n      summary: Public directory of active insurers and brokers (for \"add a policy bought elsewhere\")\n      security: []\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n  /lookups/vehicle:\n    post:\n      tags: [Lookups]\n      summary: Prefill a motor quote from a Ghana registration number\n      description: |\n        Normalises the plate (`GR 1234-23`) and looks it up in the cache, then the configured provider\n        (DVLA / partner API when `DVLA_API_URL` is set). `found: false` just means \"ask the customer\" —\n        quoting never depends on it. Returns vehicle facts only (make, model, year, body, colour,\n        engine, seats, use), never the keeper. Rate-limited (write bucket).\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/VehicleLookupInput\" } } }\n      responses:\n        \"200\":\n          description: Lookup result\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties: { data: { $ref: \"#/components/schemas/VehicleLookupResult\" } }\n        \"400\": { $ref: \"#/components/responses/Error\" }\n  /needs-assessment:\n    get:\n      tags: [Catalogue]\n      summary: The \"help me choose\" questions\n      security: []\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n    post:\n      tags: [Catalogue]\n      summary: Run the needs assessment and store the answers\n      description: Works signed-in (bearer) or anonymously (pass `anonymousId`). Returns categories to consider — not product advice.\n      security: [{}, { bearerAuth: [] }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/NeedsAssessmentInput\" } } }\n      responses:\n        \"200\":\n          description: Suggestions\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties: { data: { $ref: \"#/components/schemas/NeedsResult\" } }\n\n  /requests:\n    get:\n      tags: [Requests]\n      summary: The customer's requests\n      parameters:\n        - { $ref: \"#/components/parameters/Limit\" }\n        - { $ref: \"#/components/parameters/Before\" }\n        - { name: status, in: query, schema: { $ref: \"#/components/schemas/RequestStatus\" } }\n        - { name: open, in: query, schema: { type: string, enum: [\"true\", \"false\"] } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Page\" }\n    post:\n      tags: [Requests]\n      summary: Create (and by default submit) a request\n      description: |\n        Validates `risk` against the category's `risk_schema`, routes exactly one broker of record,\n        prices estimates from approved rating rules and creates document tasks. `source` is recorded as `mobile`.\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/CreateRequestInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"400\": { $ref: \"#/components/responses/Error\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /requests/{id}:\n    get:\n      tags: [Requests]\n      summary: Request detail — customer-visible timeline, tasks, broker, documents, applications, payments, policies\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"404\": { $ref: \"#/components/responses/Error\" }\n  /requests/{id}/cancel:\n    post:\n      tags: [Requests]\n      summary: Cancel an open request (customer)\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        content: { application/json: { schema: { type: object, properties: { reason: { type: string, maxLength: 500 } } } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /requests/{id}/quotes:\n    get:\n      tags: [Requests]\n      summary: Quotes, comparison result and disclosure text\n      description: |\n        `comparison` is the engine output (`insurersCompared`, `productsCompared`, `criteria`, `ranked`, `paidPlacements`,\n        `materialExclusions`, `disclaimer`). Show `summary` (e.g. \"3 quotes from 3 participating insurers compared\"),\n        each quote's `statusLabel`, `labels` (explained, never an unexplained \"best\"), `valid_until` and `comparedAt`.\n        Paid placements are listed separately and never ranked.\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      responses:\n        \"200\":\n          description: Quotes\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties: { data: { $ref: \"#/components/schemas/QuotesResult\" } }\n  /requests/{id}/disclosure:\n    post:\n      tags: [Requests]\n      summary: Acknowledge the broker-of-record disclosure (required before applying). Idempotent.\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        content: { application/json: { schema: { $ref: \"#/components/schemas/DisclosureAckInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /requests/{id}/share:\n    post:\n      tags: [Requests]\n      summary: Save & share the comparison (link, WhatsApp or email)\n      description: |\n        Creates a share token valid for 14 days. `url` opens a public, read-only comparison\n        (`/q/{token}`) that shows quote summaries only — never the customer's name, reference or risk\n        details beyond the cover title. `whatsappUrl` is a `https://wa.me/?text=` link with `text`\n        prefilled; `channel: email` also emails the summary to `email` (defaults to the account email).\n        \"Resume later\" needs nothing extra: the request itself is saved — `GET /requests`.\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        content: { application/json: { schema: { $ref: \"#/components/schemas/ShareQuotesInput\" } } }\n      responses:\n        \"201\":\n          description: Share created\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties: { data: { $ref: \"#/components/schemas/ShareResult\" } }\n        \"404\": { $ref: \"#/components/responses/Error\" }\n  /requests/{id}/messages:\n    get:\n      tags: [Requests]\n      summary: Message thread with the broker (oldest first within the page)\n      parameters: [{ $ref: \"#/components/parameters/Id\" }, { $ref: \"#/components/parameters/Limit\" }, { $ref: \"#/components/parameters/Before\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Page\" }\n    post:\n      tags: [Requests]\n      summary: Send a message on the thread\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/PostMessageInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n  /requests/{id}/tasks/{taskId}/complete:\n    post:\n      tags: [Requests]\n      summary: Complete a customer task (document tasks need `documentId`)\n      parameters:\n        - { $ref: \"#/components/parameters/Id\" }\n        - { name: taskId, in: path, required: true, schema: { type: string, format: uuid } }\n      requestBody:\n        content: { application/json: { schema: { $ref: \"#/components/schemas/CompleteTaskInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n\n  /documents/upload-url:\n    post:\n      tags: [Documents]\n      summary: Get a signed upload URL in the private documents bucket\n      description: |\n        Path layout `{customerId}/{scope}/{uuid}-{fileName}`. Then `PUT` the file bytes to `signedUrl`\n        with the returned headers, then confirm with `POST /documents` (body provided in `confirm.body`).\n        Uploading is not the same as notifying the insurer — the broker delivers documents.\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/UploadUrlInput\" } } }\n      responses:\n        \"200\":\n          description: Upload target\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties:\n                      data:\n                        type: object\n                        properties:\n                          bucket: { type: string }\n                          path: { type: string }\n                          token: { type: string }\n                          signedUrl: { type: string, format: uri }\n                          method: { type: string, enum: [PUT] }\n                          headers: { type: object, additionalProperties: { type: string } }\n                          expiresInSeconds: { type: integer }\n                          confirm: { type: object }\n  /documents:\n    post:\n      tags: [Documents]\n      summary: Confirm an upload and create the document record\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/ConfirmUploadInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"400\": { $ref: \"#/components/responses/Error\" }\n  /documents/{id}/url:\n    get:\n      tags: [Documents]\n      summary: Signed download URL (valid 5 minutes)\n      parameters: [{ $ref: \"#/components/parameters/Id\" }, { name: download, in: query, schema: { type: string, enum: [\"true\", \"false\"] } }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n\n  /applications:\n    post:\n      tags: [Applications & payments]\n      summary: Apply for a ready-to-accept quote\n      description: Requires the broker disclosure to have been acknowledged and the quote to be `ready_to_accept` and unexpired. Idempotent per quote.\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/ApplyInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /payments:\n    post:\n      tags: [Applications & payments]\n      summary: Start payment for a submitted application\n      description: |\n        Revalidates the quote at checkout. Premiums settle to the insurer (Paystack subaccount, the insurer's\n        Hubtel merchant account, or the insurer's bank account) — never to Covva.\n        Open `authorizationUrl` in an in-app browser; for a direct MoMo prompt (`momo` given) `authorizationUrl`\n        is null — show `displayText` and poll `GET /payments/{id}`. Pass `callbackUrl` =\n        `https://<host>/api/payments/return` from the app to be redirected to `covva://payments/return`.\n        **Bank transfer** (`channel: bank_transfer`): `authorizationUrl` is null and `bankTransfer` holds the\n        account, amount and the reference to quote; the payment stays `pending` until the credit is confirmed\n        (automatically for a dedicated virtual account, otherwise by the insurer/admin reconciliation) — keep\n        polling or wait for the `payment.succeeded` notification. `provider` says which rail took the payment\n        (`paystack`, `hubtel`, `bank_transfer`, `simulator`).\n        In test environments without provider keys a **sandbox simulator** page is returned instead.\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/InitPaymentRequest\" } } }\n      responses:\n        \"201\":\n          description: Payment started\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties: { data: { $ref: \"#/components/schemas/InitiatePaymentResult\" } }\n        \"409\": { $ref: \"#/components/responses/Error\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n        \"503\": { $ref: \"#/components/responses/Error\" }\n  /payments/{id}:\n    get:\n      tags: [Applications & payments]\n      summary: Poll a payment (re-verifies pending Paystack payments)\n      description: \"`coverActive` is true only when the insurer has issued the policy.\"\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n\n  /policies:\n    get:\n      tags: [Policies]\n      summary: Policy wallet\n      parameters: [{ name: status, in: query, schema: { $ref: \"#/components/schemas/PolicyStatus\" } }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n  /policies/{id}:\n    get:\n      tags: [Policies]\n      summary: Policy detail with cover wording, documents, claims and disclosure\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n    patch:\n      tags: [Policies]\n      summary: Rename a policy (nickname only)\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { type: object, required: [nickname], properties: { nickname: { type: [string, \"null\"], maxLength: 60 } } } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n  /policies/{id}/documents:\n    get:\n      tags: [Policies]\n      summary: Policy documents with short-lived signed URLs\n      description: |\n        Every document on the policy with a 15-minute signed download URL. Documents generated by the platform on\n        the insurer's behalf (schedule, certificate, motor sticker, premium receipt) are flagged `generated: true`\n        and carry their `sha256`; each embeds a QR code that opens `verifyUrl`. `verificationCode` is the\n        10-character code behind that QR (null for policies bought elsewhere).\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      responses:\n        \"200\":\n          description: Documents\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties:\n                      data:\n                        type: object\n                        properties:\n                          policyId: { type: string, format: uuid }\n                          policyNumber: { type: [string, \"null\"] }\n                          verificationCode: { type: [string, \"null\"] }\n                          stickerNumber: { type: [string, \"null\"] }\n                          verifyUrl: { type: [string, \"null\"], format: uri }\n                          documents:\n                            type: array\n                            items:\n                              type: object\n                              properties:\n                                id: { type: string, format: uuid }\n                                kind: { type: string, description: \"policy_schedule | certificate | sticker | receipt | policy_wording | endorsement | other\" }\n                                fileName: { type: string }\n                                mimeType: { type: [string, \"null\"] }\n                                sizeBytes: { type: [integer, \"null\"] }\n                                sha256: { type: [string, \"null\"] }\n                                generated: { type: boolean }\n                                uploadedByParty: { type: string }\n                                createdAt: { type: string, format: date-time }\n                                url: { type: [string, \"null\"], format: uri, description: \"Signed URL, valid for expiresInSeconds\" }\n                                expiresInSeconds: { type: integer }\n        \"404\": { $ref: \"#/components/responses/Error\" }\n  /policies/external:\n    post:\n      tags: [Policies]\n      summary: Add a policy bought elsewhere (shown as \"Added by you\")\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/AddExternalPolicyInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n  /policies/{id}/renewal:\n    post:\n      tags: [Policies]\n      summary: One-tap renewal — refreshed quotes for the same risk (or a switch review for external policies)\n      description: |\n        Creates a renewal request for the policy's risk with the policy's broker kept as broker of record and\n        estimates refreshed from current rates. `renewal` holds `sameInsurer` (the \"Renew with <insurer>\" offer:\n        `oneTap` is true when it is binding — apply and pay in one step), `alternatives` (cheapest first),\n        `savings` and `insurersCompared` (show \"1 insurer compared\" honestly). Existing cover is never\n        cancelled. Renewal prices are estimates until the insurer confirms.\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        content: { application/json: { schema: { $ref: \"#/components/schemas/RenewalInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"409\": { $ref: \"#/components/responses/Error\" }\n\n  /claims:\n    get:\n      tags: [Claims]\n      summary: The customer's claims\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n    post:\n      tags: [Claims]\n      summary: Report a claim to the broker\n      description: \"Reporting is not approval: show `disclaimer`. Returns the evidence checklist (`requiredEvidence`).\"\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/ReportClaimInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /claims/{id}:\n    get:\n      tags: [Claims]\n      summary: Claim detail, timeline and documents\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n  /claims/{id}/withdraw:\n    post:\n      tags: [Claims]\n      summary: Withdraw a claim before the insurer decides\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        content: { application/json: { schema: { type: object, properties: { reason: { type: string, maxLength: 500 } } } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n\n  /claims/{id}/timeline:\n    get:\n      tags: [Claims]\n      summary: Customer-facing journey with expected times\n      description: |\n        Stages `reported → acknowledged (within 24 h) → assessing (about 5 working days) → decision → payment (within\n        10 working days of approval)`, each with `at` (reached) or `expectedBy` / `expectedLabel`, plus `next` (what to expect,\n        `overdue`) and the raw events. Never implies approval.\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n  /claims/{id}/messages:\n    get:\n      tags: [Claims]\n      summary: The claim thread (customer, broker, insurer)\n      description: Oldest first. Internal partner notes are never returned to customers. `canMessage` says whether the caller may post.\n      parameters:\n        - { $ref: \"#/components/parameters/Id\" }\n        - { in: query, name: limit, schema: { type: integer, default: 50, maximum: 100 } }\n        - { in: query, name: before, schema: { type: string, format: date-time } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n    post:\n      tags: [Claims]\n      summary: Send a message in the claim thread\n      description: Attachments reference documents already uploaded with `POST /documents` (`claimId`). Notifies the other parties (push, in-app, email).\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/ClaimMessageInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /claims/{id}/info-requests:\n    get:\n      tags: [Claims]\n      summary: Information the insurer or broker has asked for\n      description: \"`items[]` of `claim_info_requests` (open first): `kind` document | information | inspection, `message`, `due_at`, `fulfilled_at`, `document_id`, `response`.\"\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n  /claims/{id}/info-requests/{reqId}/fulfil:\n    post:\n      tags: [Claims]\n      summary: Answer an information request\n      description: Link a document uploaded with `POST /documents` (`claimId`) and/or reply in writing. The requester is notified.\n      parameters:\n        - { $ref: \"#/components/parameters/Id\" }\n        - { in: path, name: reqId, required: true, schema: { type: string, format: uuid } }\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/FulfilInfoRequestInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /claims/{id}/video:\n    post:\n      tags: [Claims]\n      summary: Upload a short video of the damage or scene\n      description: |\n        ≤ 90 seconds and ≤ 50 MB; MP4, WebM or QuickTime. JSON with base64 `content`, or `multipart/form-data` with a `file`\n        part and the same field names. Measure `durationSeconds` on the device (the server rejects longer clips).\n        Stored as a `claim_video` document under `documents/{customerId}/claims/{claimId}/video-….`\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        required: true\n        content:\n          application/json: { schema: { $ref: \"#/components/schemas/ClaimVideoUploadInput\" } }\n          multipart/form-data: { schema: { type: object, properties: { file: { type: string, format: binary }, durationSeconds: { type: integer }, caption: { type: string } } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"400\": { $ref: \"#/components/responses/Error\" }\n  /claims/{id}/jobs:\n    get:\n      tags: [Claims]\n      summary: Repairs, towing and treatment arranged on the claim\n      description: Each job carries the partner's name, address and phone, `status` (requested → accepted → in_progress → completed | cancelled) and `direct_billing` (the insurer settles with the partner; the customer pays nothing upfront).\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n  /service-partners:\n    get:\n      tags: [Claims]\n      summary: Approved post-claim partner directory (public)\n      description: Garages, towing, hospitals, clinics, pharmacies and assessors by `kind` and `region`. Pass `insurerOrgId` to get `directBilling` per partner.\n      security: []\n      parameters:\n        - { in: query, name: kind, schema: { type: string, enum: [garage, towing, hospital, clinic, pharmacy, assessor] } }\n        - { in: query, name: region, schema: { type: string } }\n        - { in: query, name: insurerOrgId, schema: { type: string, format: uuid } }\n        - { in: query, name: q, schema: { type: string } }\n        - { in: query, name: limit, schema: { type: integer, default: 100, maximum: 200 } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n\n  /complaints:\n    get:\n      tags: [Complaints]\n      summary: The customer's complaints\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n    post:\n      tags: [Complaints]\n      summary: File a complaint (routed to the broker, insurer or platform; SLA from settings)\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/FileComplaintInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n\n  /notifications:\n    get:\n      tags: [Notifications & devices]\n      summary: In-app notifications (with `deepLink` for the app) and unread count\n      parameters: [{ $ref: \"#/components/parameters/Limit\" }, { $ref: \"#/components/parameters/Before\" }, { name: unread, in: query, schema: { type: string, enum: [\"true\", \"false\"] } }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Page\" }\n  /notifications/read:\n    post:\n      tags: [Notifications & devices]\n      summary: Mark notifications read\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema: { type: object, properties: { ids: { type: array, items: { type: string, format: uuid }, maxItems: 200 }, all: { type: boolean } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n  /devices:\n    post:\n      tags: [Notifications & devices]\n      summary: Register an Expo push token (moves the token to this user if it existed)\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/RegisterDeviceInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n  /devices/{token}:\n    delete:\n      tags: [Notifications & devices]\n      summary: Unregister a push token (URL-encode it). Call on sign-out.\n      parameters: [{ name: token, in: path, required: true, schema: { type: string } }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n\n  /ai/assistant:\n    post:\n      tags: [AI]\n      summary: Streaming customer assistant (AI SDK UI message stream)\n      description: |\n        Same handler as `/api/ai/assistant`. Use `useChat` with `DefaultChatTransport({ api, headers: { Authorization }, body: { requestId?, policyId?, threadId? } })`.\n        The response is a Server-Sent Events UI message stream (`x-vercel-ai-ui-message-stream: v1`), not an ApiResult.\n        Response header `x-thread-id` identifies the stored conversation; pass it back as `threadId`.\n        Tools are read-only (policies, request status, quote comparison, glossary, needs assessment, draft message to broker — never sends).\n        Rate limit: 15 burst, ~6/min. 503 `unavailable` when the `ai_assistant` flag is off.\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/AssistantRequest\" } } }\n      responses:\n        \"200\": { description: UI message stream, content: { text/event-stream: { schema: { type: string } } } }\n        \"503\": { $ref: \"#/components/responses/Error\" }\n\n  /partner/requests:\n    get:\n      tags: [Partner API]\n      summary: Requests routed to the broker, or submitted to the insurer (scope requests:read)\n      security: [{ apiKey: [] }]\n      parameters:\n        - { $ref: \"#/components/parameters/Limit\" }\n        - { $ref: \"#/components/parameters/Before\" }\n        - { name: status, in: query, schema: { $ref: \"#/components/schemas/RequestStatus\" } }\n        - { name: updatedSince, in: query, schema: { type: string, format: date-time } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Page\" }\n        \"401\": { $ref: \"#/components/responses/Error\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n  /partner/quotes:\n    post:\n      tags: [Partner API]\n      summary: Post a quote for a request (scope quotes:write)\n      description: Brokers quote for appointed insurers on their routed requests; insurers quote only for themselves on requests submitted to them. A `ready_to_accept` quote moves the request to `quotes_ready` and notifies the customer.\n      security: [{ apiKey: [] }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/BrokerQuoteInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /partner/policies/{id}/issue:\n    post:\n      tags: [Partner API]\n      summary: Issue a pending policy — activates cover (insurer keys only, scope policies:issue)\n      description: Requires a confirmed payment. Records `policy_active` usage, completes the request and notifies the customer.\n      security: [{ apiKey: [] }]\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/IssuePolicyBody\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n        \"409\": { $ref: \"#/components/responses/Error\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /partner/claims/{id}/status:\n    post:\n      tags: [Partner API]\n      summary: Update a claim's status or decision (insurer keys only, scope claims:write)\n      security: [{ apiKey: [] }]\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/PartnerClaimStatusInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n\n  /partner/offers:\n    get:\n      tags: [Partner API]\n      summary: Requests offered to the broker (claim model, Addendum 2 D2/E)\n      description: |\n        Open offers by default (`status=offered`, soonest deadline first). Works with a broker member's bearer token\n        (RLS limits rows to their organisations) or a broker API key (scope `requests:read`). Each open item carries\n        `acceptUrl` (web one-tap link `/partner/offers/accept/{token}`) and `deepLink` (`covva://offers/accept/{token}`).\n        The customer's identity is only shared once the offer is accepted; `request.risk_data` is available to decide.\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters:\n        - { $ref: \"#/components/parameters/Limit\" }\n        - { $ref: \"#/components/parameters/Before\" }\n        - { name: status, in: query, schema: { type: string, enum: [offered, accepted, declined, expired, withdrawn], default: offered } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Page\" }\n        \"401\": { $ref: \"#/components/responses/Error\" }\n  /partner/offers/{id}:\n    post:\n      tags: [Partner API]\n      summary: Accept or decline an offered request\n      description: |\n        `accept` makes the organisation the broker of record (first to accept wins; every other open offer is withdrawn;\n        a second accept returns 422). `decline` passes the request on; when the whole round has declined it is re-offered\n        at once, otherwise when the timer expires (`routing.offer_timeout_minutes`, default 30). Callers must be an\n        adviser/supervisor/admin/owner of the offered broker (bearer) or use that broker's API key (scope `requests:read`).\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/OfferResponseInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"404\": { $ref: \"#/components/responses/Error\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n\n\n  # --- Broker workspace on mobile (Addendum 4 §2) — also usable by insurer users on the web client and by partner keys ---\n  /partner/dashboard:\n    get:\n      tags: [Partner API]\n      summary: Workspace dashboard — KPIs, commission summary and open work counts\n      description: |\n        Sales funnel for the range (`days` = 7, 30 or 90; per-day `series` for sparklines), renewals due in 30 days,\n        claims summary, SLA performance, lapses, the current month's commission (only for owners/admins/finance or\n        keys with `finance:read`; otherwise `commission` is null and `commissionVisible` false) and counts of open\n        offers / requests / submissions / claims. Dual-membership users pick the organisation with `orgId` (or the\n        `X-Covva-Org` header); otherwise the stored `activeWorkspace` or the only partner membership is used.\n        Insurer workspaces are refused on `X-Covva-Client: mobile` (`details.reason = insurer_web_only`).\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters:\n        - { $ref: \"#/components/parameters/OrgId\" }\n        - { name: days, in: query, schema: { type: integer, enum: [7, 30, 90], default: 30 } }\n      responses:\n        \"200\":\n          description: Dashboard\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties: { data: { $ref: \"#/components/schemas/PartnerDashboard\" } }\n        \"401\": { $ref: \"#/components/responses/Error\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n  /partner/renewals:\n    get:\n      tags: [Partner API]\n      summary: Policies due for renewal within N days (scope policies:read)\n      description: |\n        Active policies of the organisation ending within `days` (default 30, max 365), soonest first, with the\n        customer's display name, `contactAllowed` (latest data-sharing consent for your organisation type),\n        `marketingAllowed` and the renewal request if one exists. Brokers (broker of record) get full names and\n        contact details; insurer users get first name + initial and no contact details.\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters:\n        - { $ref: \"#/components/parameters/OrgId\" }\n        - { name: days, in: query, schema: { type: integer, minimum: 1, maximum: 365, default: 30 } }\n      responses:\n        \"200\":\n          description: Renewals\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties:\n                      data:\n                        type: object\n                        properties:\n                          windowDays: { type: integer }\n                          count: { type: integer }\n                          items: { type: array, items: { $ref: \"#/components/schemas/RenewalItem\" } }\n                          note: { type: string }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n  /partner/commission:\n    get:\n      tags: [Partner API]\n      summary: Commission summary for a month (owners/admins/finance; scope finance:read)\n      description: Earned (brokers) or payable (insurers) from the ledger, `paid` from statements marked paid, `outstanding` = earned − paid. Period defaults to the current month.\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters:\n        - { $ref: \"#/components/parameters/OrgId\" }\n        - { name: period, in: query, schema: { type: string, pattern: \"^\\\\d{4}-(0[1-9]|1[0-2])$\", example: \"2026-10\" } }\n      responses:\n        \"200\":\n          description: Commission\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties: { data: { $ref: \"#/components/schemas/CommissionSummary\" } }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n  /partner/statements:\n    get:\n      tags: [Partner API]\n      summary: Settlement statements, newest period first (owners/admins/finance; scope finance:read)\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters:\n        - { $ref: \"#/components/parameters/OrgId\" }\n        - { name: limit, in: query, schema: { type: integer, minimum: 1, maximum: 60, default: 24 } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Page\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n  /partner/statements/{id}:\n    get:\n      tags: [Partner API]\n      summary: One statement with its ledger lines and a 10-minute PDF link when rendered\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters: [{ $ref: \"#/components/parameters/Id\" }, { $ref: \"#/components/parameters/OrgId\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n        \"404\": { $ref: \"#/components/responses/Error\" }\n  /partner/claims:\n    get:\n      tags: [Partner API]\n      summary: Claims the organisation assists (brokers) or decides (insurers) (scope claims:read)\n      description: Newest first. `view=open` (default) hides decided/closed claims; `status` filters one status. Each item carries `statusLabel` and `customerName` (initials only for insurers).\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters:\n        - { $ref: \"#/components/parameters/OrgId\" }\n        - { name: view, in: query, schema: { type: string, enum: [open, decided, all], default: open } }\n        - { name: status, in: query, schema: { type: string, enum: [draft, reported, delivered_to_insurer, acknowledged, under_assessment, info_requested, approved, partially_approved, rejected, paid, closed, withdrawn] } }\n        - { name: policyId, in: query, schema: { type: string, format: uuid } }\n        - { name: customerId, in: query, schema: { type: string, format: uuid } }\n        - { $ref: \"#/components/parameters/Limit\" }\n        - { $ref: \"#/components/parameters/Before\" }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Page\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n  /partner/claims/{id}/updates:\n    post:\n      tags: [Partner API]\n      summary: Broker records a claim step or a note from the app\n      description: |\n        Same rules as the web claims desk: a broker (owner/admin/supervisor/adviser) may mark a claim\n        `delivered_to_insurer` and, only while the insurer hasn't acted on it, `acknowledged` / `under_assessment` /\n        `info_requested`; otherwise send a note only. Decisions are insurer-only (`POST /partner/claims/{id}/status`).\n        Notifies the customer (push) when the status changes or the note is visible to them.\n      security: [{ bearerAuth: [] }]\n      parameters: [{ $ref: \"#/components/parameters/Id\" }, { $ref: \"#/components/parameters/OrgId\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/PartnerClaimUpdateInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n        \"404\": { $ref: \"#/components/responses/Error\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /partner/claims/{id}/info-requests:\n    get:\n      tags: [Partner API]\n      summary: Information requests on a claim the organisation services\n      security: [{ bearerAuth: [] }]\n      parameters: [{ $ref: \"#/components/parameters/Id\" }, { $ref: \"#/components/parameters/OrgId\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n    post:\n      tags: [Partner API]\n      summary: Ask the customer (or the broker) for a document, information or an inspection slot\n      description: |\n        Brokers (owner/admin/supervisor/adviser) and insurer claims teams. The requested party is notified (customers by push,\n        in-app, email and SMS) and can answer from the claim page or `POST /claims/{id}/info-requests/{reqId}/fulfil`.\n        Insurers may set `setStatus: true` to move the claim to `info_requested` in the same call.\n      security: [{ bearerAuth: [] }]\n      parameters: [{ $ref: \"#/components/parameters/Id\" }, { $ref: \"#/components/parameters/OrgId\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/ClaimInfoRequestInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /partner/claims/{id}/jobs:\n    get:\n      tags: [Partner API]\n      summary: Jobs arranged on a claim\n      security: [{ bearerAuth: [] }]\n      parameters: [{ $ref: \"#/components/parameters/Id\" }, { $ref: \"#/components/parameters/OrgId\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n    post:\n      tags: [Partner API]\n      summary: Assign an approved service partner to the claim\n      description: \"`directBilling: true` is only accepted when the partner direct-bills the claim's insurer (`GET /service-partners?insurerOrgId=`). The customer is notified with the partner's contact details.\"\n      security: [{ bearerAuth: [] }]\n      parameters: [{ $ref: \"#/components/parameters/Id\" }, { $ref: \"#/components/parameters/OrgId\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/ClaimJobInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n    patch:\n      tags: [Partner API]\n      summary: Track a job (status, estimate, invoice, schedule)\n      security: [{ bearerAuth: [] }]\n      parameters: [{ $ref: \"#/components/parameters/Id\" }, { $ref: \"#/components/parameters/OrgId\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/UpdateClaimJobInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n\n  /partner/customers:\n    get:\n      tags: [Partner API]\n      summary: The broker's clients (brokers only; scope requests:read)\n      description: Active `customer_broker_assignments` plus customers whose requests or policies name the organisation as broker of record. Insurer workspaces get `403 forbidden`.\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters:\n        - { $ref: \"#/components/parameters/OrgId\" }\n        - { name: q, in: query, description: Name, email, phone or business name contains, schema: { type: string, maxLength: 100 } }\n        - { name: limit, in: query, schema: { type: integer, minimum: 1, maximum: 100, default: 50 } }\n        - { name: offset, in: query, schema: { type: integer, minimum: 0, default: 0 } }\n      responses:\n        \"200\":\n          description: Clients\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties:\n                      data:\n                        type: object\n                        properties:\n                          items: { type: array, items: { $ref: \"#/components/schemas/ClientSummary\" } }\n                          total: { type: integer }\n                          limit: { type: integer }\n                          offset: { type: integer }\n                          nextOffset: { type: [integer, \"null\"] }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n  /partner/customers/{id}:\n    get:\n      tags: [Partner API]\n      summary: One client with policies, requests, claims and assignment history (brokers only)\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters: [{ $ref: \"#/components/parameters/Id\" }, { $ref: \"#/components/parameters/OrgId\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n        \"404\": { $ref: \"#/components/responses/Error\" }\n  /partner/documents:\n    post:\n      tags: [Partner API]\n      summary: Upload a document from the phone camera in one call\n      description: |\n        Policy schedules, certificates, IDs and claim evidence for a request, policy or claim the organisation\n        services. Send JSON with base64 `content` (plain or `data:` URL) or `multipart/form-data` with a `file`\n        part and the same field names. Max 20 MB; PDF, JPEG, PNG, WebP, HEIC or Word. Creates the `documents` row,\n        a `document_uploaded` request event, and tells the customer when a policy document is added to their wallet.\n        The two-step flow (`/documents/upload-url` → `/documents`) is still available for large files.\n      security: [{ bearerAuth: [] }]\n      parameters: [{ $ref: \"#/components/parameters/OrgId\" }]\n      requestBody:\n        required: true\n        content:\n          application/json: { schema: { $ref: \"#/components/schemas/PartnerDocumentUploadInput\" } }\n          multipart/form-data:\n            schema:\n              type: object\n              required: [file]\n              properties:\n                file: { type: string, format: binary }\n                fileName: { type: string }\n                mimeType: { type: string }\n                kind: { $ref: \"#/components/schemas/DocumentKind\" }\n                requestId: { type: string, format: uuid }\n                policyId: { type: string, format: uuid }\n                claimId: { type: string, format: uuid }\n                taskId: { type: string, format: uuid }\n                deliveredToInsurer: { type: boolean }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"400\": { $ref: \"#/components/responses/Error\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n  /partner/messages:\n    get:\n      tags: [Partner API]\n      summary: A request thread as the servicing organisation (oldest first, with internal notes)\n      description: Marks the customer's messages as read by the broker. Customers use `GET /requests/{id}/messages`.\n      security: [{ bearerAuth: [] }]\n      parameters:\n        - { name: request_id, in: query, required: true, schema: { type: string, format: uuid } }\n        - { $ref: \"#/components/parameters/OrgId\" }\n        - { name: limit, in: query, schema: { type: integer, minimum: 1, maximum: 100, default: 50 } }\n        - { $ref: \"#/components/parameters/Before\" }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Page\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n        \"404\": { $ref: \"#/components/responses/Error\" }\n    post:\n      tags: [Partner API]\n      summary: Message the customer on a request (push + in-app + email), or add an internal note\n      security: [{ bearerAuth: [] }]\n      parameters: [{ $ref: \"#/components/parameters/OrgId\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/PartnerMessageInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n        \"404\": { $ref: \"#/components/responses/Error\" }\n  /partner/profile:\n    get:\n      tags: [Partner API]\n      summary: Organisation profile, the caller's role and insurer/broker links (appointments)\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters: [{ $ref: \"#/components/parameters/OrgId\" }]\n      responses:\n        \"200\":\n          description: Profile\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties: { data: { $ref: \"#/components/schemas/PartnerProfile\" } }\n    patch:\n      tags: [Partner API]\n      summary: Update contact details (owners and admins)\n      description: Only `contactEmail`, `contactPhone`, `website`, `address`, `region` and `description`. Licence and legal details change through registration or Covva admin.\n      security: [{ bearerAuth: [] }, { apiKey: [] }]\n      parameters: [{ $ref: \"#/components/parameters/OrgId\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/UpdatePartnerProfileInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n\n  /fx:\n    get:\n      tags: [Diaspora payments]\n      security: []\n      summary: Indicative FX display rates (GHS per 1 unit) and the disclosure text\n      description: |\n        Diaspora payers see the GHS premium in GBP, USD, EUR or CAD. Rates are indicative (source and time\n        are returned; `manual` rates are flagged); the insurer always receives the GHS contract amount and the\n        card issuer / PSP applies the final rate. `amount` (GHS) returns a full `quote` with the disclosure.\n      parameters:\n        - { name: currency, in: query, schema: { type: string, enum: [GHS, GBP, USD, EUR, CAD], default: GHS } }\n        - { name: amount, in: query, description: GHS amount to convert (indicative), schema: { type: number } }\n      responses:\n        \"200\":\n          description: Rates\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties: { data: { $ref: \"#/components/schemas/FxRates\" } }\n  /subscriptions:\n    get:\n      tags: [Diaspora payments]\n      summary: The caller's sponsor subscriptions and saved payment methods (no card numbers)\n      responses:\n        \"200\":\n          description: Subscriptions\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties:\n                      data:\n                        type: object\n                        properties:\n                          items: { type: array, items: { $ref: \"#/components/schemas/SponsorSubscription\" } }\n                          paymentMethods: { type: array, items: { $ref: \"#/components/schemas/PaymentMethod\" } }\n    post:\n      tags: [Diaspora payments]\n      summary: Start recurring premium collections for a policy the caller pays for\n      description: |\n        Every collection is a GHS premium payment to the insurer (same split/ledger as a checkout), charged to the\n        sponsor's saved card on the cadence; the foreign amount is indicative. Needs a saved method — pay once by\n        card with `saveMethod: true` (or `sponsorSubscription` on `POST /payments`, which creates the subscription\n        automatically after the first payment). Monthly collections on a yearly quote need the insurer to allow instalments.\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/CreateSubscriptionInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /subscriptions/{id}/pause:\n    post:\n      tags: [Diaspora payments]\n      summary: Pause collections (cover may lapse when a premium falls due)\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"404\": { $ref: \"#/components/responses/Error\" }\n  /subscriptions/{id}/cancel:\n    post:\n      tags: [Diaspora payments]\n      summary: Cancel collections; existing cover runs to its end date\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody: { content: { application/json: { schema: { type: object, properties: { reason: { type: string, maxLength: 500 } } } } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n  /bundles:\n    get:\n      tags: [Diaspora payments]\n      security: []\n      summary: Published product bundles (e.g. the Parents' Care Pack) with an indicative GHS estimate\n      description: Each item becomes its own request/quote/policy; the discount is confirmed by the insurer on the binding quotes. `getStartedUrl` opens the web flow with `?bundle=`.\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n  /property/{policyId}/updates:\n    get:\n      tags: [Diaspora payments]\n      summary: Construction / site photo updates on a property policy\n      parameters: [{ name: policyId, in: path, required: true, schema: { type: string, format: uuid } }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n    post:\n      tags: [Diaspora payments]\n      summary: Record a site photo already uploaded with POST /documents/upload-url (scope policies)\n      description: Customer or sponsor of the policy only (RLS). The photo is visible to the broker and insurer.\n      parameters: [{ name: policyId, in: path, required: true, schema: { type: string, format: uuid } }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/PropertyUpdateInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n  /property/{policyId}/inspections:\n    get:\n      tags: [Diaspora payments]\n      summary: Partner site inspections on a property policy (status, visit date, report)\n      parameters: [{ name: policyId, in: path, required: true, schema: { type: string, format: uuid } }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n    post:\n      tags: [Diaspora payments]\n      summary: Ask for a partner site inspection (customer or sponsor)\n      description: Covva assigns an inspection partner; the partner schedules and files the report; the INSURER decides what it means for cover. One open inspection per policy.\n      parameters: [{ name: policyId, in: path, required: true, schema: { type: string, format: uuid } }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/RequestInspectionInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"409\": { $ref: \"#/components/responses/Error\" }\n\n  /verify:\n    get:\n      tags: [Verification]\n      summary: Public policy check (QR code or insurer + policy number)\n      description: |\n        Unauthenticated and rate-limited (30 per IP, refilling slowly). Pass `code` (the 10-character\n        verification code from a wallet QR / `verifyUrl`) **or** `insurer` (organisation slug) + `policyNumber`.\n        Returns only non-personal fields: valid, status, insurerName, categoryName, coverStart, coverEnd and\n        policyNumberMasked (last 4). A \"not found\" result is not proof that a risk is uninsured — the policy may\n        have been bought outside Covva.\n      security: []\n      parameters:\n        - { name: code, in: query, schema: { type: string, pattern: \"^[0-9A-HJKMNP-TV-Z]{10}$\" } }\n        - { name: insurer, in: query, description: Insurer organisation slug, schema: { type: string } }\n        - { name: policyNumber, in: query, schema: { type: string, minLength: 3 } }\n      responses:\n        \"200\":\n          description: Verification result\n          content:\n            application/json:\n              schema:\n                allOf:\n                  - $ref: \"#/components/schemas/OkEnvelope\"\n                  - properties:\n                      data:\n                        type: object\n                        required: [valid]\n                        properties:\n                          valid: { type: boolean }\n                          status: { type: string, description: \"active | outside cover dates | pending issuance | cancelled | expired | …\" }\n                          insurerName: { type: string }\n                          categoryName: { type: string }\n                          coverStart: { type: [string, \"null\"], format: date }\n                          coverEnd: { type: [string, \"null\"], format: date }\n                          policyNumberMasked: { type: [string, \"null\"], description: \"Last 4 characters visible\" }\n                          message: { type: string }\n        \"400\": { $ref: \"#/components/responses/Error\" }\n        \"429\": { $ref: \"#/components/responses/Error\" }\n  /family/beneficiaries:\n    get:\n      tags: [Family (diaspora)]\n      summary: Family members the caller looks after\n      description: Ghana Card numbers are masked (`ghana_card_masked`); `has_account` tells whether the beneficiary signed up with that phone.\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n    post:\n      tags: [Family (diaspora)]\n      summary: Add a family member in Ghana\n      description: Phone must be a Ghana number (normalised to +233…). Consent starts `pending`; send a code next.\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/CreateBeneficiaryInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"409\": { $ref: \"#/components/responses/Error\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /family/beneficiaries/{id}:\n    get:\n      tags: [Family (diaspora)]\n      summary: One family member with their consent records\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n    patch:\n      tags: [Family (diaspora)]\n      summary: Edit a family member (changing the phone resets consent)\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/UpdateBeneficiaryInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n  /family/beneficiaries/{id}/consent:\n    post:\n      tags: [Family (diaspora)]\n      summary: Send a consent code (and signed link) to the beneficiary's phone\n      description: |\n        The 6-digit code goes to the **beneficiary** by SMS or WhatsApp together with a signed `/consent/{token}` link;\n        it is never returned to the sponsor. Codes last 15 minutes, links 7 days. Rate limited.\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        content: { application/json: { schema: { $ref: \"#/components/schemas/RequestConsentInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"429\": { $ref: \"#/components/responses/Error\" }\n  /family/beneficiaries/{id}/consent/confirm:\n    post:\n      tags: [Family (diaspora)]\n      summary: Confirm with the code the beneficiary read out\n      description: 5 attempts, then the code is locked until a new one is sent (`422 business_rule`).\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/ConfirmConsentInput\" } } }\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /family/dashboard:\n    get:\n      tags: [Family (diaspora)]\n      summary: Family dashboard\n      description: Beneficiaries (+ consents), sponsorships, policies paid for, next renewal, payment schedule (one-off payments and recurring sponsor subscriptions), claims and `summary`.\n      responses:\n        \"200\": { description: Dashboard, content: { application/json: { schema: { allOf: [{ $ref: \"#/components/schemas/OkEnvelope\" }, { properties: { data: { $ref: \"#/components/schemas/FamilyDashboard\" } } }] } } } }\n  /family/sponsorships:\n    get:\n      tags: [Family (diaspora)]\n      summary: The caller's sponsorships\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n    post:\n      tags: [Family (diaspora)]\n      summary: Link the payer to a beneficiary and a request or policy (optionally as a gift)\n      description: Needs the beneficiary's `data_sharing` consent. Becomes `active` once the policy exists. One sponsorship per policy.\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/CreateSponsorshipInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"409\": { $ref: \"#/components/responses/Error\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /family/sponsorships/{id}/reveal:\n    post:\n      tags: [Family (diaspora)]\n      summary: Open a gift (beneficiary's linked account)\n      description: Records `gift_revealed_at` and returns `gift_message`. The sponsor cannot call this.\n      parameters: [{ $ref: \"#/components/parameters/Id\" }]\n      responses:\n        \"200\": { $ref: \"#/components/responses/Ok\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n  /family/claims:\n    post:\n      tags: [Family (diaspora)]\n      summary: Report a claim on behalf of a beneficiary (claims by proxy)\n      description: Needs an active sponsorship and the beneficiary's `proxy_claims` consent; `422` otherwise. The claim stays the policyholder's (`reported_by_user_id` = sponsor). Reporting is not approval.\n      requestBody:\n        required: true\n        content: { application/json: { schema: { $ref: \"#/components/schemas/ProxyClaimInput\" } } }\n      responses:\n        \"201\": { $ref: \"#/components/responses/Ok\" }\n        \"403\": { $ref: \"#/components/responses/Error\" }\n        \"422\": { $ref: \"#/components/responses/Error\" }\n\n  /openapi:\n    get:\n      tags: [System]\n      summary: This document (YAML)\n      security: []\n      responses:\n        \"200\": { description: OpenAPI document, content: { application/yaml: { schema: { type: string } } } }\n\nwebhooks:\n  request.created:\n    post:\n      tags: [Webhooks]\n      summary: A request was routed to the broker of record\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  request.status_changed:\n    post:\n      tags: [Webhooks]\n      summary: A request changed status (data.from_status, data.status)\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  quote.ready:\n    post:\n      tags: [Webhooks]\n      summary: Quotes were sent to the customer, or a binding quote was posted\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  application.submitted:\n    post:\n      tags: [Webhooks]\n      summary: The customer applied for a quote\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  payment.succeeded:\n    post:\n      tags: [Webhooks]\n      summary: Premium confirmed by the payment provider (policy pending issuance — not active)\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  policy.issued:\n    post:\n      tags: [Webhooks]\n      summary: The insurer issued the policy; cover is active\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  claim.reported:\n    post:\n      tags: [Webhooks]\n      summary: A claim was reported (reporting is not approval)\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  claim.status_changed:\n    post:\n      tags: [Webhooks]\n      summary: A claim changed status\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  complaint.filed:\n    post:\n      tags: [Webhooks]\n      summary: A complaint owned by your organisation was filed\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n  test.ping:\n    post:\n      tags: [Webhooks]\n      summary: Test delivery sent from the settings page\n      requestBody: { content: { application/json: { schema: { $ref: \"#/components/schemas/WebhookEnvelope\" } } } }\n      responses: { \"2xx\": { description: Acknowledged } }\n\ncomponents:\n  securitySchemes:\n    bearerAuth:\n      type: http\n      scheme: bearer\n      bearerFormat: Supabase access token (JWT)\n    apiKey:\n      type: apiKey\n      in: header\n      name: x-api-key\n      description: \"Partner key `imk_<prefix>_<secret>`; the platform stores only sha256(key).\"\n\n  parameters:\n    CovvaClient:\n      name: X-Covva-Client\n      in: header\n      required: false\n      description: Which client is calling. Missing = `web`. Insurer and staff accounts are refused on `mobile`.\n      schema: { type: string, enum: [mobile, web, partner-web], default: web }\n    Id: { name: id, in: path, required: true, schema: { type: string, format: uuid } }\n    Limit: { name: limit, in: query, schema: { type: integer, minimum: 1, maximum: 100, default: 25 } }\n    Before: { name: before, in: query, description: Cursor (ISO timestamp from `nextCursor`), schema: { type: string, format: date-time } }\n    OrgId: { name: orgId, in: query, required: false, description: \"Organisation to act for when the user belongs to several (also accepted as the `X-Covva-Org` header). Defaults to the stored active workspace or the only partner membership.\", schema: { type: string, format: uuid } }\n\n  responses:\n    Ok:\n      description: Success\n      content: { application/json: { schema: { $ref: \"#/components/schemas/OkEnvelope\" } } }\n    Page:\n      description: A page of items\n      content:\n        application/json:\n          schema:\n            allOf:\n              - $ref: \"#/components/schemas/OkEnvelope\"\n              - properties:\n                  data:\n                    type: object\n                    properties:\n                      items: { type: array, items: { type: object } }\n                      nextCursor: { type: [string, \"null\"], format: date-time }\n    Error:\n      description: Error\n      content: { application/json: { schema: { $ref: \"#/components/schemas/ErrorEnvelope\" } } }\n    Me:\n      description: Current user\n      content:\n        application/json:\n          schema:\n            allOf:\n              - $ref: \"#/components/schemas/OkEnvelope\"\n              - properties:\n                  data:\n                    type: object\n                    properties:\n                      profile: { type: object, description: \"profiles row; Ghana Card returned as ghana_card_last4 only\" }\n                      memberships: { type: array, items: { type: object } }\n                      isPartner: { type: boolean }\n                      workspaces: { type: array, items: { $ref: \"#/components/schemas/Workspace\" }, description: \"Customer workspace first, then one per broker/insurer membership\" }\n                      activeWorkspace: { $ref: \"#/components/schemas/ActiveWorkspace\" }\n                      client: { type: string, enum: [mobile, web, partner-web], description: \"Echo of X-Covva-Client\" }\n                      flags: { type: object, additionalProperties: { type: boolean }, description: \"feature_flags (e.g. demo_mode, ai_assistant)\" }\n                      consents: { type: object, additionalProperties: { type: object } }\n                      versions: { type: object, properties: { terms: { type: [string, \"null\"] }, privacy: { type: [string, \"null\"] } } }\n                      needsConsent: { type: boolean }\n\n  schemas:\n    Workspace:\n      type: object\n      required: [type, mobileAllowed, allowed]\n      properties:\n        type: { type: string, enum: [customer, broker, insurer] }\n        orgId: { type: string, format: uuid }\n        orgName: { type: string }\n        role: { type: string, description: \"member_role (owner, admin, supervisor, adviser, underwriter, claims_officer, finance, viewer)\" }\n        mobileAllowed: { type: boolean, description: \"Usable from the mobile app (false for insurer workspaces)\" }\n        allowed: { type: boolean, description: \"Usable from the calling client\" }\n    ActiveWorkspace:\n      type: object\n      required: [type]\n      properties:\n        type: { type: string, enum: [customer, broker, insurer] }\n        orgId: { type: string, format: uuid }\n    SetActiveWorkspaceInput:\n      type: object\n      required: [type]\n      properties:\n        type: { type: string, enum: [customer, broker, insurer] }\n        orgId: { type: string, format: uuid, description: \"Required unless type is customer\" }\n    OkEnvelope:\n      type: object\n      required: [ok, data]\n      properties:\n        ok: { const: true }\n        data: {}\n    ErrorEnvelope:\n      type: object\n      required: [ok, error]\n      properties:\n        ok: { const: false }\n        error:\n          type: object\n          required: [code, message]\n          properties:\n            code: { $ref: \"#/components/schemas/ErrorCode\" }\n            message: { type: string, description: Safe to show to users }\n            details: {}\n    ErrorCode:\n      type: string\n      enum: [unauthorised, forbidden, not_found, invalid_input, business_rule, conflict, rate_limited, unavailable, internal_error]\n\n    RequestStatus:\n      type: string\n      enum: [draft, submitted, awaiting_customer_info, adviser_action, insurer_response, quotes_ready, payment_confirmation, policy_documents, completed, cancelled, closed_no_cover]\n    QuoteStatus:\n      type: string\n      enum: [estimate, awaiting_underwriting, ready_to_accept, accepted, expired, declined, withdrawn]\n    PolicyStatus:\n      type: string\n      enum: [pending_issuance, active, lapsed, cancelled, expired, renewed]\n    ClaimStatus:\n      type: string\n      enum: [draft, reported, delivered_to_insurer, acknowledged, under_assessment, info_requested, approved, partially_approved, rejected, paid, closed, withdrawn]\n    ComplaintStatus:\n      type: string\n      enum: [open, acknowledged, investigating, resolved, escalated_nic, closed]\n    PaymentStatus:\n      type: string\n      enum: [pending, processing, succeeded, failed, refunded, reversed, abandoned]\n    CategoryAvailability:\n      type: string\n      enum: [integrated, broker_assisted, planned]\n    DocumentKind:\n      type: string\n      enum: [id_document, vehicle_registration, drivers_licence, photo, proof_of_address, medical, policy_schedule, certificate, policy_wording, receipt, endorsement, claim_evidence, police_report, invoice, other]\n    ConsentType:\n      type: string\n      enum: [terms, privacy, marketing, data_sharing_broker, data_sharing_insurer, ai_assistance]\n\n    RiskField:\n      type: object\n      required: [key, label, type]\n      properties:\n        key: { type: string }\n        label: { type: string }\n        type: { type: string, enum: [text, number, currency, select, multiselect, boolean, date, region] }\n        required: { type: boolean }\n        min: { type: number }\n        max: { type: number }\n        placeholder: { type: string }\n        help: { type: string }\n        options: { type: array, items: { type: object, properties: { value: { type: string }, label: { type: string } } } }\n    Category:\n      type: object\n      properties:\n        id: { type: string, format: uuid }\n        slug: { type: string }\n        name: { type: string }\n        short_description: { type: [string, \"null\"] }\n        icon: { type: [string, \"null\"], description: lucide icon name }\n        segment: { type: string, enum: [personal, business, specialist] }\n        availability: { $ref: \"#/components/schemas/CategoryAvailability\" }\n        availabilityLabel: { type: string }\n        availabilityPromise: { type: string }\n        risk_schema: { type: array, items: { $ref: \"#/components/schemas/RiskField\" } }\n        required_documents: { type: array, items: { $ref: \"#/components/schemas/DocumentKind\" } }\n        regulatory_note: { type: [string, \"null\"] }\n        default_sla_hours: { type: integer }\n\n    UpdateProfileInput:\n      type: object\n      properties:\n        fullName: { type: string, maxLength: 200 }\n        preferredName: { type: [string, \"null\"] }\n        phone: { type: [string, \"null\"], pattern: \"^\\\\+?\\\\d{9,15}$\" }\n        accountType: { type: string, enum: [individual, business] }\n        businessName: { type: [string, \"null\"] }\n        dateOfBirth: { type: [string, \"null\"], format: date }\n        ghanaCardNumber: { type: [string, \"null\"], pattern: \"^GHA-\\\\d{9}-\\\\d$\" }\n        region: { type: [string, \"null\"] }\n        city: { type: [string, \"null\"] }\n        locale: { type: string }\n        avatarUrl: { type: [string, \"null\"], format: uri }\n        notificationPrefs: { type: object, properties: { email: { type: boolean }, sms: { type: boolean }, push: { type: boolean }, whatsapp: { type: boolean } } }\n        onboarded: { const: true }\n    RecordConsentsInput:\n      type: object\n      required: [consents]\n      properties:\n        consents:\n          type: array\n          minItems: 1\n          maxItems: 10\n          items:\n            type: object\n            required: [type, granted]\n            properties:\n              type: { $ref: \"#/components/schemas/ConsentType\" }\n              granted: { type: boolean }\n              version: { type: string }\n              context: { type: string }\n    NeedsAssessmentInput:\n      type: object\n      required: [answers]\n      properties:\n        answers: { type: object, additionalProperties: { oneOf: [{ type: string }, { type: array, items: { type: string } }, { type: boolean }] } }\n        anonymousId: { type: string }\n    NeedsResult:\n      type: object\n      properties:\n        id: { type: [string, \"null\"], format: uuid }\n        suggestions:\n          type: array\n          items:\n            type: object\n            properties:\n              slug: { type: string }\n              name: { type: string }\n              priority: { type: string, enum: [essential, recommended, consider] }\n              why: { type: string }\n              availability: { $ref: \"#/components/schemas/CategoryAvailability\" }\n        needsAdviser: { type: boolean }\n        adviserReason: { type: [string, \"null\"] }\n        note: { type: string }\n\n    CreateRequestInput:\n      type: object\n      required: [categorySlug, risk]\n      properties:\n        categorySlug: { type: string }\n        type: { type: string, enum: [new_cover, renewal, switch, endorsement, service], default: new_cover }\n        risk: { type: object, additionalProperties: true, description: \"Answers keyed by the category's risk_schema field keys\" }\n        relatedPolicyId: { type: string, format: uuid }\n        needsAssessmentId: { type: string, format: uuid }\n        submit: { type: boolean, default: true }\n        talkToExpert: { type: boolean, default: false, description: \"Ask for advice: always routed to a broker, whatever the insurer's integration level\" }\n    DisclosureAckInput:\n      type: object\n      properties:\n        stage: { type: string, enum: [before_advice, before_application, broker_change], default: before_application }\n        method: { type: string, enum: [in_app, sms, email, call], default: in_app }\n    PostMessageInput:\n      type: object\n      required: [body]\n      properties:\n        body: { type: string, minLength: 1, maxLength: 4000 }\n        attachments: { type: array, items: { type: object, required: [documentId, name], properties: { documentId: { type: string, format: uuid }, name: { type: string } } } }\n    CompleteTaskInput:\n      type: object\n      properties:\n        documentId: { type: string, format: uuid }\n        note: { type: string, maxLength: 1000 }\n\n    Quote:\n      type: object\n      properties:\n        id: { type: string, format: uuid }\n        status: { $ref: \"#/components/schemas/QuoteStatus\" }\n        statusLabel: { type: string }\n        statusHint: { type: [string, \"null\"] }\n        is_binding: { type: boolean }\n        premium: { type: number }\n        taxes: { type: number }\n        fees: { type: number }\n        currency: { type: string, example: GHS }\n        billing_period: { type: string }\n        sum_insured: { type: [number, \"null\"] }\n        excess: { type: [number, \"null\"] }\n        coverage: { type: array, items: { type: object, properties: { key: { type: string }, label: { type: string }, included: { type: boolean } } } }\n        limits: { type: object }\n        excesses: { type: object }\n        exclusions: { type: array, items: { type: string } }\n        key_exclusion: { type: [string, \"null\"] }\n        waiting_period_days: { type: integer }\n        optional_benefits: { type: array, items: { type: object, properties: { key: { type: string }, label: { type: string }, premium: { type: number } } } }\n        valid_until: { type: [string, \"null\"], format: date-time }\n        expired: { type: boolean }\n        paid_placement: { type: boolean }\n        commission_disclosure: { type: [string, \"null\"] }\n        labels: { type: array, items: { type: string }, description: \"Explained labels, e.g. Lowest premium\" }\n        demo: { type: boolean }\n        insurer: { type: object, properties: { id: { type: string }, name: { type: string }, slug: { type: string }, logo_url: { type: [string, \"null\"] } } }\n        product: { type: [object, \"null\"], properties: { id: { type: string }, name: { type: string }, tier: { type: [string, \"null\"] } } }\n    QuotesResult:\n      type: object\n      properties:\n        request: { type: object }\n        broker: { type: [object, \"null\"] }\n        quotes: { type: array, items: { $ref: \"#/components/schemas/Quote\" } }\n        comparison:\n          type: object\n          properties:\n            engineVersion: { type: string }\n            insurersCompared: { type: integer }\n            productsCompared: { type: integer }\n            criteria: { type: object }\n            ranked: { type: array, items: { type: object } }\n            paidPlacements: { type: array, items: { type: object } }\n            materialExclusions: { type: array, items: { type: object } }\n            disclaimer: { type: string }\n        summary: { type: string }\n        disclosure: { type: [string, \"null\"] }\n        comparedAt: { type: string, format: date-time }\n        demoMode: { type: boolean }\n        demoDisclaimer: { type: [string, \"null\"] }\n\n    UploadUrlInput:\n      type: object\n      required: [scope, fileName, mimeType, sizeBytes]\n      properties:\n        scope: { type: string, enum: [requests, policies, claims, profile] }\n        fileName: { type: string, maxLength: 200 }\n        mimeType: { type: string, enum: [application/pdf, image/jpeg, image/png, image/webp, image/heic, application/msword, application/vnd.openxmlformats-officedocument.wordprocessingml.document] }\n        sizeBytes: { type: integer, maximum: 20971520 }\n        kind: { $ref: \"#/components/schemas/DocumentKind\" }\n        requestId: { type: string, format: uuid }\n        policyId: { type: string, format: uuid }\n        claimId: { type: string, format: uuid }\n        taskId: { type: string, format: uuid }\n    ConfirmUploadInput:\n      allOf:\n        - $ref: \"#/components/schemas/UploadUrlInput\"\n        - type: object\n          required: [path]\n          properties:\n            path: { type: string }\n            checksum: { type: string }\n\n    ApplyInput:\n      type: object\n      required: [quoteId, declarations, acceptTerms]\n      properties:\n        quoteId: { type: string, format: uuid }\n        declarations: { type: object, additionalProperties: { oneOf: [{ type: boolean }, { type: string }] } }\n        selectedBenefits: { type: array, items: { type: string }, description: optional_benefits keys }\n        acceptTerms: { const: true }\n    InitPaymentRequest:\n      type: object\n      required: [applicationId]\n      properties:\n        applicationId: { type: string, format: uuid }\n        channel: { type: string, enum: [mobile_money, card, bank_transfer], default: mobile_money }\n        callbackUrl: { type: string, format: uri }\n        momo:\n          type: object\n          required: [phone, provider]\n          properties:\n            phone: { type: string, example: \"0244123456\" }\n            provider: { type: string, enum: [mtn, vod, atl] }\n    InitiatePaymentResult:\n      type: object\n      properties:\n        paymentId: { type: string, format: uuid }\n        reference: { type: string }\n        authorizationUrl: { type: [string, \"null\"], format: uri }\n        status: { $ref: \"#/components/schemas/PaymentStatus\" }\n        displayText: { type: [string, \"null\"] }\n        provider: { type: string, enum: [paystack, hubtel, simulator, bank_transfer] }\n        bankTransfer:\n          oneOf:\n            - { type: \"null\" }\n            - $ref: \"#/components/schemas/BankTransferInstructions\"\n    BankTransferInstructions:\n      type: object\n      required: [bank, accountName, accountNumber, reference, kind, amount, currency, instructions]\n      properties:\n        bank: { type: string }\n        accountName: { type: string }\n        accountNumber: { type: string }\n        reference: { type: string, description: Quote this on the transfer; it is matched at reconciliation }\n        kind: { type: string, enum: [insurer_account, paystack_dva], description: insurer's own account, or a Paystack dedicated virtual account unique to the customer (auto-confirms) }\n        amount: { type: number }\n        currency: { type: string, example: GHS }\n        instructions: { type: string, description: Plain-language instructions to show the customer }\n    VehicleLookupInput:\n      type: object\n      required: [registration]\n      properties:\n        registration: { type: string, example: \"GR 1234-23\" }\n    VehicleLookupResult:\n      type: object\n      required: [registration, found]\n      properties:\n        registration: { type: string, description: Normalised plate }\n        found: { type: boolean }\n        source: { type: [string, \"null\"], enum: [dvla, manual, cache, null] }\n        data:\n          type: [object, \"null\"]\n          properties:\n            make: { type: string }\n            model: { type: string }\n            year: { type: integer }\n            body: { type: string }\n            colour: { type: string }\n            chassis_last4: { type: string }\n            engine_cc: { type: integer }\n            seats: { type: integer }\n            use: { type: string, enum: [private, commercial] }\n        fetchedAt: { type: string, format: date-time }\n    ShareQuotesInput:\n      type: object\n      properties:\n        channel: { type: string, enum: [link, whatsapp, email], default: link }\n        email: { type: string, format: email, description: Recipient for `email` (defaults to the account email) }\n    ShareResult:\n      type: object\n      required: [id, token, url, channel, expiresAt, text, whatsappUrl]\n      properties:\n        id: { type: string, format: uuid }\n        token: { type: string }\n        url: { type: string, format: uri, description: Public read-only comparison page }\n        channel: { type: string, enum: [link, whatsapp, email] }\n        expiresAt: { type: string, format: date-time }\n        text: { type: string, description: Plain-text summary (WhatsApp / SMS friendly) }\n        whatsappUrl: { type: string, format: uri }\n        emailSent: { type: boolean }\n\n    WebhookEnvelope:\n      type: object\n      required: [id, event, created_at, attempt, org_id, data]\n      properties:\n        id: { type: string, description: Delivery id (stable across retries — de-duplicate on it) }\n        event: { type: string, enum: [request.created, request.status_changed, quote.ready, application.submitted, payment.succeeded, policy.issued, claim.reported, claim.status_changed, complaint.filed, test.ping] }\n        created_at: { type: string, format: date-time }\n        attempt: { type: integer, minimum: 1, maximum: 5 }\n        org_id: { type: string, format: uuid, description: The organisation the endpoint belongs to }\n        data:\n          type: object\n          additionalProperties: true\n          description: Ids, references, statuses, amounts and dates only. Never personal data.\n          properties:\n            request_id: { type: string, format: uuid }\n            reference: { type: string }\n            status: { type: string }\n            from_status: { type: string }\n            policy_id: { type: string, format: uuid }\n            claim_id: { type: string, format: uuid }\n            complaint_id: { type: string, format: uuid }\n            payment_id: { type: string, format: uuid }\n            application_id: { type: string, format: uuid }\n            quote_id: { type: string, format: uuid }\n    AddExternalPolicyInput:\n      type: object\n      required: [categorySlug, policyNumber, coverStart, coverEnd]\n      description: Give either `insurerOrgId` (an insurer on the platform) or `insurerName` (any other insurer; stored as `external_insurer_name`, no organisation is created).\n      properties:\n        categorySlug: { type: string }\n        insurerOrgId: { type: string, format: uuid, description: From GET /catalog/insurers }\n        insurerName: { type: string, minLength: 2, maxLength: 120, description: Insurer not on the platform, as printed on the policy }\n        policyNumber: { type: string }\n        coverStart: { type: string, format: date }\n        coverEnd: { type: string, format: date }\n        premium: { type: number }\n        sumInsured: { type: number }\n        nickname: { type: string, maxLength: 60 }\n        documentId: { type: string, format: uuid }\n    RenewalInput:\n      type: object\n      properties:\n        risk: { type: object, additionalProperties: true, description: Defaults to the original request's risk details }\n        changes: { type: string, maxLength: 2000, description: \"What has changed (posted to the broker)\" }\n\n    ReportClaimInput:\n      type: object\n      required: [policyId, incidentType, incidentAt, description]\n      properties:\n        policyId: { type: string, format: uuid }\n        incidentType: { type: string, example: Accident }\n        incidentAt: { type: string, format: date-time }\n        location:\n          description: Free text, or the phone's location\n          oneOf:\n            - { type: string, maxLength: 300 }\n            - { type: object, properties: { lat: { type: number }, lng: { type: number }, accuracy: { type: number }, address: { type: string, maxLength: 300 } } }\n        description: { type: string, minLength: 10, maxLength: 5000 }\n        amountClaimed: { type: number }\n        policeReportDocumentId: { type: string, format: uuid, description: A police report already uploaded with POST /documents }\n    FileComplaintInput:\n      type: object\n      required: [subject, description, category]\n      properties:\n        subject: { type: string, minLength: 3, maxLength: 200 }\n        description: { type: string, minLength: 10, maxLength: 5000 }\n        category: { type: string, enum: [advice, service, claims, payment, data_privacy, technology, other] }\n        againstParty: { type: string, enum: [broker, insurer, platform], default: broker }\n        requestId: { type: string, format: uuid }\n        policyId: { type: string, format: uuid }\n        claimId: { type: string, format: uuid }\n        desiredOutcome: { type: string, maxLength: 2000 }\n    RegisterDeviceInput:\n      type: object\n      required: [token, platform]\n      properties:\n        token: { type: string, example: \"ExponentPushToken[xxxxxxxxxxxxxxxxxxxxxx]\" }\n        platform: { type: string, enum: [ios, android, web] }\n        provider: { type: string, enum: [expo, fcm, apns, webpush], default: expo }\n        appVersion: { type: string }\n    AssistantRequest:\n      type: object\n      required: [messages]\n      properties:\n        messages: { type: array, maxItems: 60, items: { type: object, description: \"AI SDK UIMessage { id, role, parts }\" } }\n        requestId: { type: string, format: uuid }\n        policyId: { type: string, format: uuid }\n        threadId: { type: string, format: uuid }\n\n    BrokerQuoteInput:\n      type: object\n      required: [requestId, insurerOrgId, status, premium]\n      properties:\n        requestId: { type: string, format: uuid }\n        insurerOrgId: { type: string, format: uuid }\n        productVersionId: { type: string, format: uuid }\n        status: { type: string, enum: [estimate, awaiting_underwriting, ready_to_accept] }\n        premium: { type: number, minimum: 0 }\n        excess: { type: number, minimum: 0 }\n        sumInsured: { type: number, minimum: 0 }\n        keyExclusion: { type: string }\n        validUntil: { type: string, format: date-time, description: Defaults to 14 days for ready_to_accept }\n        brokerNote: { type: string, maxLength: 2000 }\n    IssuePolicyBody:\n      type: object\n      required: [policyNumber, coverStart, coverEnd]\n      properties:\n        policyNumber: { type: string, minLength: 3, maxLength: 60 }\n        coverStart: { type: string, format: date }\n        coverEnd: { type: string, format: date }\n    PartnerClaimStatusInput:\n      type: object\n      required: [status]\n      properties:\n        status: { type: string, enum: [acknowledged, under_assessment, info_requested, approved, partially_approved, rejected, paid, closed] }\n        note: { type: string, maxLength: 2000 }\n        insurerReference: { type: string }\n        decisionAmount: { type: number, minimum: 0 }\n        visibleToCustomer: { type: boolean, default: true }\n    OfferResponseInput:\n      type: object\n      required: [action]\n      properties:\n        action: { type: string, enum: [accept, decline] }\n        reason: { type: string, maxLength: 500, description: Optional decline reason (kept for routing analytics) }\n    Offer:\n      type: object\n      description: A request offered to a broker (`GET /partner/offers` item).\n      properties:\n        id: { type: string, format: uuid }\n        request_id: { type: string, format: uuid }\n        status: { type: string, enum: [offered, accepted, declined, expired, withdrawn] }\n        round: { type: integer, description: Offer round (1 = first batch of brokers) }\n        offered_at: { type: string, format: date-time }\n        responds_by: { type: string, format: date-time, description: Accept before this or the request moves on }\n        acceptUrl: { type: [string, \"null\"], description: One-tap accept link (web) }\n        deepLink: { type: [string, \"null\"], description: \"covva://offers/accept/{token}\" }\n        request: { type: object, description: \"id, reference, title, type, status, risk_data, talk_to_expert, complexity_flags, category\" }\n\n    # --- Broker workspace on mobile (Addendum 4 §2) ---\n    DocumentKind:\n      type: string\n      enum: [id_document, vehicle_registration, drivers_licence, photo, proof_of_address, medical, policy_schedule, certificate, policy_wording, receipt, endorsement, claim_evidence, police_report, invoice, other]\n    SalesDay:\n      type: object\n      description: One day of the sales funnel (from `partner_sales_summary`).\n      properties:\n        day: { type: string, format: date }\n        requests: { type: integer }\n        quotes: { type: integer }\n        conversions: { type: integer, description: Applications accepted }\n        policies_issued: { type: integer }\n        premium: { type: number }\n        platform_fee: { type: number }\n        broker_commission: { type: number }\n    PartnerDashboard:\n      type: object\n      properties:\n        org: { type: object, properties: { id: { type: string, format: uuid }, name: { type: string }, type: { type: string, enum: [broker, insurer] }, role: { type: [string, \"null\"] } } }\n        range: { type: object, properties: { days: { type: integer }, from: { type: string, format: date }, to: { type: string, format: date } } }\n        kpis:\n          type: object\n          properties:\n            requests: { type: integer }\n            quotes: { type: integer }\n            conversions: { type: integer }\n            policiesIssued: { type: integer }\n            premium: { type: number }\n            platformFee: { type: number }\n            brokerCommission: { type: number }\n            conversionRate: { type: [number, \"null\"], description: Conversions as % of quotes }\n            change: { type: object, additionalProperties: { type: [number, \"null\"] }, description: \"% change vs the previous period per KPI\" }\n        series: { type: array, items: { $ref: \"#/components/schemas/SalesDay\" } }\n        open: { type: object, properties: { offers: { type: integer }, requests: { type: integer }, submissions: { type: integer }, claims: { type: integer } } }\n        renewals: { type: object, properties: { count: { type: integer }, windowDays: { type: integer }, next: { type: array, items: { type: object }, description: \"First 10 rows of partner_renewals (snake_case)\" } } }\n        claims:\n          type: object\n          properties:\n            byStatus: { type: object, additionalProperties: { type: integer } }\n            total: { type: integer }\n            open: { type: integer }\n            decided: { type: integer }\n            avgDaysToDecision: { type: [number, \"null\"] }\n            staleOpen: { type: integer, description: Open for more than 14 days }\n            openSlaBreaches: { type: [integer, \"null\"], description: Null until SLA timers exist }\n        sla:\n          type: object\n          properties:\n            requests_measured: { type: integer }\n            requests_on_time: { type: integer }\n            requests_breached: { type: integer }\n            requests_open_overdue: { type: integer }\n            submissions_measured: { type: integer }\n            submissions_on_time: { type: integer }\n            submissions_late: { type: integer }\n            submissions_open_overdue: { type: integer }\n            on_time_rate: { type: [number, \"null\"], description: Percentage }\n        lapses:\n          type: object\n          properties: { lapsed: { type: integer }, cancelled: { type: integer }, expired: { type: integer }, renewed: { type: integer }, active: { type: integer }, ended: { type: integer }, lapse_rate: { type: [number, \"null\"] } }\n        commission: { oneOf: [{ $ref: \"#/components/schemas/CommissionRow\" }, { type: \"null\" }] }\n        commissionVisible: { type: boolean }\n        period: { type: string, example: \"2026-10\" }\n    CommissionRow:\n      type: object\n      description: Raw row of `partner_commission_summary` (snake_case).\n      properties:\n        period: { type: string }\n        period_start: { type: string, format: date }\n        period_end: { type: string, format: date }\n        currency: { type: string }\n        earned: { type: number }\n        paid: { type: number }\n        outstanding: { type: number }\n        revenue_share: { type: number }\n        platform_fee: { type: number }\n        entries: { type: integer }\n        statement_id: { type: [string, \"null\"], format: uuid }\n        statement_status: { type: [string, \"null\"], enum: [draft, issued, paid, null] }\n        statement_net_due: { type: [number, \"null\"] }\n    CommissionSummary:\n      type: object\n      properties:\n        period: { type: string, example: \"2026-10\" }\n        periodStart: { type: string, format: date }\n        periodEnd: { type: string, format: date }\n        currency: { type: string }\n        earned: { type: number, description: Brokers — commission credited; insurers — commission payable }\n        paid: { type: number }\n        outstanding: { type: number }\n        revenueShare: { type: number }\n        platformFee: { type: number }\n        entries: { type: integer }\n        statement: { type: [object, \"null\"], properties: { id: { type: string, format: uuid }, status: { type: string }, netDue: { type: number } } }\n        side: { type: string, enum: [earned, payable] }\n        note: { type: string }\n    RenewalItem:\n      type: object\n      properties:\n        policyId: { type: string, format: uuid }\n        reference: { type: string }\n        policyNumber: { type: [string, \"null\"] }\n        category: { type: object, properties: { id: { type: string, format: uuid }, name: { type: string } } }\n        coverEnd: { type: string, format: date }\n        daysLeft: { type: integer }\n        premium: { type: [number, \"null\"] }\n        currency: { type: string }\n        status: { type: string }\n        customer:\n          type: object\n          properties:\n            id: { type: string, format: uuid }\n            name: { type: string, description: Full name for brokers; first name + initial for insurers }\n            email: { type: [string, \"null\"], description: Brokers only }\n            phone: { type: [string, \"null\"], description: Brokers only }\n        contactAllowed: { type: boolean, description: Latest data-sharing consent for your organisation type }\n        marketingAllowed: { type: boolean }\n        renewalRequest: { type: [object, \"null\"], properties: { id: { type: string, format: uuid }, status: { type: string } } }\n        remindersSent: { type: integer }\n    PartnerClaimUpdateInput:\n      type: object\n      description: Give a status, a note, or both.\n      properties:\n        status: { type: string, enum: [delivered_to_insurer, acknowledged, under_assessment, info_requested] }\n        note: { type: string, maxLength: 2000 }\n        visibleToCustomer: { type: boolean, default: true }\n    ClientSummary:\n      type: object\n      properties:\n        id: { type: string, format: uuid }\n        name: { type: string }\n        email: { type: [string, \"null\"] }\n        phone: { type: [string, \"null\"] }\n        accountType: { type: string, enum: [individual, business] }\n        businessName: { type: [string, \"null\"] }\n        kycStatus: { type: string, enum: [unverified, pending, verified, rejected] }\n        region: { type: [string, \"null\"] }\n        city: { type: [string, \"null\"] }\n        source: { type: string, enum: [assignment, request, policy], description: How the client is linked to the broker }\n        assignedSince: { type: [string, \"null\"], format: date-time }\n        openRequests: { type: integer }\n        activePolicies: { type: integer }\n        lastRequestAt: { type: [string, \"null\"], format: date-time }\n    PartnerDocumentUploadInput:\n      type: object\n      required: [fileName, mimeType, content]\n      properties:\n        fileName: { type: string, maxLength: 200 }\n        mimeType: { type: string, enum: [application/pdf, image/jpeg, image/png, image/webp, image/heic, application/msword, application/vnd.openxmlformats-officedocument.wordprocessingml.document] }\n        kind: { $ref: \"#/components/schemas/DocumentKind\" }\n        content: { type: string, description: \"Base64 file contents (plain or data: URL), max 20 MB decoded\" }\n        requestId: { type: string, format: uuid }\n        policyId: { type: string, format: uuid }\n        claimId: { type: string, format: uuid }\n        taskId: { type: string, format: uuid }\n        deliveredToInsurer: { type: boolean, default: false }\n    PartnerMessageInput:\n      type: object\n      required: [requestId, body]\n      properties:\n        requestId: { type: string, format: uuid }\n        body: { type: string, minLength: 1, maxLength: 4000 }\n        attachments: { type: array, maxItems: 10, items: { type: object, properties: { documentId: { type: string, format: uuid }, name: { type: string } } } }\n        internal: { type: boolean, default: false, description: Team-only note, never shown to the customer }\n    PartnerProfile:\n      type: object\n      properties:\n        organisation: { type: object, description: \"organizations row: name, slug, type, status, logo_url, contact_email, contact_phone, website, address, region, NIC licence fields, integration_level\" }\n        membership: { type: [object, \"null\"], properties: { role: { type: string }, roleLabel: { type: string }, isSupervisor: { type: boolean }, canEditProfile: { type: boolean } } }\n        teamSize: { type: integer }\n        links:\n          type: object\n          description: Insurer appointments (brokers see insurers; insurers see brokers)\n          properties:\n            kind: { type: string, enum: [insurers, brokers] }\n            active: { type: integer }\n            items: { type: array, items: { type: object, properties: { id: { type: string, format: uuid }, active: { type: boolean }, organisation: { type: object }, category: { type: [object, \"null\"] }, agreementReference: { type: [string, \"null\"] }, startsOn: { type: [string, \"null\"] }, endsOn: { type: [string, \"null\"] } } } }\n        workspaces: { type: array, items: { type: object, properties: { orgId: { type: string, format: uuid }, orgName: { type: string }, type: { type: string }, role: { type: string } } } }\n    UpdatePartnerProfileInput:\n      type: object\n      minProperties: 1\n      properties:\n        contactEmail: { type: [string, \"null\"], format: email }\n        contactPhone: { type: [string, \"null\"] }\n        website: { type: [string, \"null\"], format: uri }\n        address: { type: [string, \"null\"], maxLength: 400 }\n        region: { type: [string, \"null\"], maxLength: 100 }\n        description: { type: [string, \"null\"], maxLength: 2000 }\n    ClaimMessageInput:\n      type: object\n      required: [body]\n      properties:\n        body: { type: string, minLength: 1, maxLength: 4000 }\n        attachments: { type: array, maxItems: 10, items: { type: object, required: [name], properties: { documentId: { type: string, format: uuid }, storagePath: { type: string }, name: { type: string, maxLength: 200 } } } }\n        internal: { type: boolean, default: false, description: Partner/staff-only note; rejected for customers }\n    ClaimInfoRequestInput:\n      type: object\n      required: [message]\n      properties:\n        kind: { type: string, enum: [document, information, inspection], default: document }\n        requestedParty: { type: string, enum: [customer, broker], default: customer }\n        message: { type: string, minLength: 3, maxLength: 2000 }\n        dueAt: { type: string, format: date-time }\n        setStatus: { type: boolean, default: false, description: Insurers only — also move the claim to info_requested }\n    FulfilInfoRequestInput:\n      type: object\n      description: Give a documentId, a response, or both.\n      properties:\n        documentId: { type: string, format: uuid }\n        response: { type: string, maxLength: 2000 }\n    ClaimVideoUploadInput:\n      type: object\n      required: [fileName, mimeType, content]\n      properties:\n        fileName: { type: string, maxLength: 200 }\n        mimeType: { type: string, enum: [video/mp4, video/webm, video/quicktime] }\n        durationSeconds: { type: integer, minimum: 0, description: Measured on the device; max 90 }\n        content: { type: string, description: Base64 (plain or data URL); max 50 MB decoded }\n        caption: { type: string, maxLength: 300 }\n    ClaimJobInput:\n      type: object\n      required: [servicePartnerId]\n      properties:\n        servicePartnerId: { type: string, format: uuid }\n        kind: { type: string, enum: [repair, towing, treatment, assessment, replacement, other], default: repair }\n        directBilling: { type: boolean, default: false }\n        estimate: { type: number, minimum: 0 }\n        scheduledFor: { type: string, format: date-time }\n        notes: { type: string, maxLength: 2000 }\n    UpdateClaimJobInput:\n      type: object\n      required: [jobId]\n      properties:\n        jobId: { type: string, format: uuid }\n        status: { type: string, enum: [requested, accepted, in_progress, completed, cancelled] }\n        estimate: { type: number, minimum: 0 }\n        invoiceDocumentId: { type: string, format: uuid }\n        scheduledFor: { type: [string, \"null\"], format: date-time }\n        directBilling: { type: boolean }\n        notes: { type: string, maxLength: 2000 }\n    CreateBeneficiaryInput:\n      type: object\n      required: [fullName, relationship, phone]\n      properties:\n        fullName: { type: string, minLength: 2, maxLength: 120 }\n        relationship: { type: string, enum: [parent, spouse, child, sibling, other] }\n        phone: { type: string, description: \"Ghana mobile number (024 123 4567 / +233…); stored as +233XXXXXXXXX\" }\n        email: { type: string, format: email }\n        dateOfBirth: { type: string, format: date }\n        ghanaCardNumber: { type: string, description: \"GHA-123456789-0; masked in every response\" }\n        address: { type: string, maxLength: 300 }\n        region: { type: string, maxLength: 60 }\n        notes: { type: string, maxLength: 1000 }\n    UpdateBeneficiaryInput:\n      allOf: [{ $ref: \"#/components/schemas/CreateBeneficiaryInput\" }]\n      required: []\n      minProperties: 1\n    Beneficiary:\n      type: object\n      properties:\n        id: { type: string, format: uuid }\n        full_name: { type: string }\n        relationship: { type: string, enum: [parent, spouse, child, sibling, other] }\n        phone: { type: string }\n        email: { type: [string, \"null\"] }\n        date_of_birth: { type: [string, \"null\"], format: date }\n        ghana_card_masked: { type: [string, \"null\"], example: \"GHA-•••••6789-0\" }\n        region: { type: [string, \"null\"] }\n        linked_user_id: { type: [string, \"null\"], format: uuid }\n        has_account: { type: boolean }\n        consent_status: { type: string, enum: [pending, granted, declined, expired] }\n        consent_channel: { type: [string, \"null\"], enum: [sms, whatsapp, null] }\n        consent_sent_at: { type: [string, \"null\"], format: date-time }\n        consent_granted_at: { type: [string, \"null\"], format: date-time }\n        created_at: { type: string, format: date-time }\n    RequestConsentInput:\n      type: object\n      properties:\n        kind: { type: string, enum: [data_sharing, proxy_claims, policy_purchase], default: data_sharing }\n        channel: { type: string, enum: [sms, whatsapp], default: sms }\n    ConfirmConsentInput:\n      type: object\n      required: [code]\n      properties:\n        kind: { type: string, enum: [data_sharing, proxy_claims, policy_purchase], default: data_sharing }\n        code: { type: string, pattern: \"^\\\\d{6}$\" }\n    CreateSponsorshipInput:\n      type: object\n      required: [beneficiaryId]\n      properties:\n        beneficiaryId: { type: string, format: uuid }\n        requestId: { type: string, format: uuid, description: One of requestId / policyId is required }\n        policyId: { type: string, format: uuid }\n        gift: { type: boolean, default: false }\n        giftMessage: { type: string, maxLength: 500 }\n        notifyBeneficiary: { type: boolean, default: true, description: Send the beneficiary documents, reminders and claim updates too }\n    Sponsorship:\n      type: object\n      properties:\n        id: { type: string, format: uuid }\n        sponsor_user_id: { type: string, format: uuid }\n        beneficiary_id: { type: string, format: uuid }\n        request_id: { type: [string, \"null\"], format: uuid }\n        policy_id: { type: [string, \"null\"], format: uuid }\n        status: { type: string, enum: [draft, active, ended] }\n        gift: { type: boolean }\n        gift_message: { type: [string, \"null\"] }\n        gift_revealed_at: { type: [string, \"null\"], format: date-time }\n        notify_beneficiary: { type: boolean }\n        started_at: { type: [string, \"null\"], format: date-time }\n        created_at: { type: string, format: date-time }\n    ProxyClaimInput:\n      allOf: [{ $ref: \"#/components/schemas/ReportClaimInput\" }]\n      properties:\n        evidence:\n          type: array\n          maxItems: 20\n          description: Files already uploaded under the sponsor's folder (§7 upload flow)\n          items: { type: object, required: [path, name], properties: { path: { type: string }, name: { type: string }, mime: { type: string }, size: { type: integer } } }\n    FamilyDashboard:\n      type: object\n      properties:\n        summary:\n          type: object\n          properties:\n            activePolicies: { type: integer }\n            pendingPolicies: { type: integer }\n            nextRenewal: { type: [object, \"null\"], properties: { policyId: { type: string, format: uuid }, coverEnd: { type: string, format: date }, days: { type: integer } } }\n            nextPaymentDue: { type: [object, \"null\"], properties: { paymentId: { type: string }, dueAt: { type: string }, amount: { type: [number, \"null\"] }, currency: { type: [string, \"null\"] } } }\n            openClaims: { type: integer }\n            annualPremiumGHS: { type: number }\n            coverGaps: { type: array, items: { type: object, properties: { beneficiaryId: { type: string, format: uuid }, name: { type: string }, reason: { type: string, enum: [no_cover, consent_pending, consent_declined] } } } }\n        beneficiaries: { type: array, items: { allOf: [{ $ref: \"#/components/schemas/Beneficiary\" }, { properties: { consents: { type: array, items: { type: object, properties: { kind: { type: string }, granted: { type: boolean }, granted_at: { type: [string, \"null\"] }, declined_at: { type: [string, \"null\"] }, expires_at: { type: [string, \"null\"] }, requested_at: { type: [string, \"null\"] }, locked_at: { type: [string, \"null\"] } } } } } }] } }\n        sponsorships: { type: array, items: { $ref: \"#/components/schemas/Sponsorship\" } }\n        policies: { type: array, items: { type: object, description: \"policies row (lite) + category + insurer, with sponsor_user_id / beneficiary_id\" } }\n        claims: { type: array, items: { type: object, description: \"claims row (lite) with reported_by_user_id\" } }\n        payments: { type: array, items: { type: object, description: \"payments row (lite)\" } }\n        subscriptions: { type: array, items: { type: object, description: \"sponsor_subscriptions row (lite): status, cadence, display_amount, display_currency, ghs_amount, next_charge_at\" } }\n    # --- Diaspora payments ---------------------------------------------------------\n    FxRates:\n      type: object\n      properties:\n        base: { type: string, enum: [GHS] }\n        currencies: { type: array, items: { type: string } }\n        marginPct: { type: number, description: \"Platform display buffer (% of the rate) added to the indicative foreign amount; shown to the payer, never collected by Covva\" }\n        rates:\n          type: object\n          additionalProperties:\n            type: [object, \"null\"]\n            properties:\n              rate: { type: number, description: GHS per 1 unit }\n              source: { type: string, enum: [manual, openexchangerates, bog, provider] }\n              fetchedAt: { type: string, format: date-time }\n              validUntil: { type: [string, \"null\"], format: date-time }\n              manual: { type: boolean, description: Flag the rate as a manual/indicative override in the UI }\n        selected: { type: [object, \"null\"], properties: { currency: { type: string }, rate: { type: number }, source: { type: string }, fetchedAt: { type: string }, disclosure: { type: string } } }\n        quote: { type: [object, \"null\"], $ref: \"#/components/schemas/FxQuote\" }\n        indicative: { type: boolean }\n        note: { type: string }\n    FxQuote:\n      type: object\n      description: Indicative display of a GHS amount. `ghsAmount` is the contract amount the insurer receives.\n      properties:\n        displayCurrency: { type: string, enum: [GHS, GBP, USD, EUR, CAD] }\n        ghsAmount: { type: number }\n        displayAmount: { type: number }\n        rate: { type: number, description: GHS per 1 unit after the margin }\n        baseRate: { type: number }\n        marginPct: { type: number }\n        source: { type: string }\n        quotedAt: { type: string, format: date-time }\n        indicative: { type: boolean }\n        disclosure: { type: string, description: \"Plain-language FX disclosure to show next to the price\" }\n    PaymentMethod:\n      type: object\n      description: Saved card by PSP token (never a PAN).\n      properties:\n        id: { type: string, format: uuid }\n        psp: { type: string, enum: [paystack_intl, stripe, paystack, simulator] }\n        brand: { type: [string, \"null\"] }\n        last4: { type: [string, \"null\"] }\n        exp_month: { type: [integer, \"null\"] }\n        exp_year: { type: [integer, \"null\"] }\n        billing_country: { type: [string, \"null\"] }\n        currency: { type: [string, \"null\"] }\n        is_default: { type: boolean }\n        status: { type: string, enum: [active, expired, revoked] }\n        created_at: { type: string, format: date-time }\n    SponsorSubscription:\n      type: object\n      description: \"sponsor_subscriptions row (public columns) plus `summary` from @im/core subscriptionSummary().\"\n      properties:\n        id: { type: string, format: uuid }\n        policy_id: { type: [string, \"null\"], format: uuid }\n        beneficiary_id: { type: [string, \"null\"], format: uuid }\n        cadence: { type: string, enum: [monthly, quarterly, annual] }\n        display_currency: { type: string }\n        display_amount: { type: number, description: Indicative amount in display_currency }\n        ghs_amount: { type: number, description: Contract amount collected for the insurer per charge }\n        fx_rate: { type: [number, \"null\"] }\n        fx_source: { type: [string, \"null\"] }\n        payment_method_id: { type: [string, \"null\"], format: uuid }\n        psp: { type: string }\n        status: { type: string, enum: [active, past_due, paused, cancelled] }\n        next_charge_at: { type: string, format: date-time }\n        last_charged_at: { type: [string, \"null\"], format: date-time }\n        past_due_since: { type: [string, \"null\"], format: date-time }\n        failures: { type: integer, description: \"Consecutive failed collections (retries 1d, 3d, 7d, then past_due)\" }\n        summary:\n          type: object\n          properties:\n            cadenceLabel: { type: string }\n            statusLabel: { type: string }\n            tone: { type: string, enum: [ok, danger, wait, neutral] }\n            hint: { type: string }\n            amountLabel: { type: string }\n            nextChargeLabel: { type: string }\n            failures: { type: integer }\n            daysToNext: { type: [integer, \"null\"] }\n    CreateSubscriptionInput:\n      type: object\n      properties:\n        policyId: { type: string, format: uuid }\n        applicationId: { type: string, format: uuid, description: \"Alternative to policyId: the paid application whose policy the subscription continues\" }\n        cadence: { type: string, enum: [monthly, quarterly, annual], default: monthly }\n        displayCurrency: { type: string, enum: [GHS, GBP, USD, EUR, CAD], default: GHS }\n        paymentMethodId: { type: string, format: uuid, description: Defaults to the sponsor's default saved method }\n        beneficiaryId: { type: string, format: uuid }\n    PropertyUpdateInput:\n      type: object\n      required: [storagePath]\n      properties:\n        storagePath: { type: string, description: \"Path returned by POST /documents/upload-url (must be in the caller's own folder)\" }\n        caption: { type: string, maxLength: 500 }\n        takenAt: { type: string, format: date-time }\n    RequestInspectionInput:\n      type: object\n      required: [address]\n      properties:\n        address: { type: string, minLength: 5, maxLength: 500 }\n        gps: { type: object, properties: { lat: { type: number }, lng: { type: number } } }\n        notes: { type: string, maxLength: 2000 }\n";
